/* Скрипты лендинга «Слива». Подключается из index.html: <script src="script.js">.
   Вынесен в отдельный файл, чтобы политика безопасности (CSP) разрешала только скрипты с этого сайта. */
'use strict';

/* ================= Logger =================
   Уровни: debug < info < warn < error.
   Каждая запись — объект, готовый к отправке во внешнюю систему
   (Sentry, ELK, свой API): подключается в функции transport. */
const Logger = (() => {
  const LEVELS = { debug: 10, info: 20, warn: 30, error: 40 };
  const minLevel = 'debug';
  const sessionId = Math.random().toString(36).slice(2, 10);

  function transport(entry) {
    // Пример: fetch('/api/logs', { method: 'POST', body: JSON.stringify(entry) })
    // В опубликованной демо-версии внешние запросы заблокированы — пишем только в консоль.
  }

  function log(level, message, context = {}) {
    if (LEVELS[level] < LEVELS[minLevel]) return;
    const entry = {
      timestamp: new Date().toISOString(),
      level,
      message,
      sessionId,
      page: location.pathname,
      ...context
    };
    (console[level] || console.log)(`[${level.toUpperCase()}] ${message}`, entry);
    try { transport(entry); } catch (_) { /* логгер не должен ронять страницу */ }
    return entry;
  }

  return {
    debug: (m, c) => log('debug', m, c),
    info:  (m, c) => log('info', m, c),
    warn:  (m, c) => log('warn', m, c),
    error: (m, err, c = {}) => log('error', m, {
      ...c,
      error: { name: err?.name, message: err?.message, stack: err?.stack }
    })
  };
})();

window.addEventListener('error', e =>
  Logger.error('window.error', e.error || new Error(e.message), { fn: 'global', source: e.filename, line: e.lineno }));
window.addEventListener('unhandledrejection', e =>
  Logger.error('unhandledrejection', e.reason instanceof Error ? e.reason : new Error(String(e.reason)), { fn: 'global' }));

/* ================= Палитра ================= */
const SHADES = [
  { code: '01', name: 'Молочный', hex: '#F1E4E1' },
  { code: '04', name: 'Нюд',      hex: '#D6A894' },
  { code: '09', name: 'Пудра',    hex: '#D9A0AE' },
  { code: '12', name: 'Слива',    hex: '#6E1F45' },
  { code: '17', name: 'Вишня',    hex: '#8E1230' },
  { code: '23', name: 'Шалфей',   hex: '#8FA087' },
  { code: '28', name: 'Ночь',     hex: '#243049' },
  { code: '31', name: 'Графит',   hex: '#3A3438' }
];
const SHAPE_NAMES = { oval: 'овал', almond: 'миндаль', soft: 'мягкий квадрат', square: 'квадрат' };

const state = { shade: SHADES[3], shape: 'almond' };
const fan = document.getElementById('fan');
const label = document.getElementById('shadeLabel');
const swatchBox = document.getElementById('swatches');
const noteField = document.getElementById('f-note');
let noteTouched = false;

function paletteText() {
  return `Оттенок № ${state.shade.code} «${state.shade.name}», форма — ${SHAPE_NAMES[state.shape]}`;
}
function syncNote() {
  if (!noteTouched) noteField.value = paletteText();
}

/* ================= Анимации ================= */
const polishRoot = document.getElementById('top'); // здесь хранится --polish для всей страницы
const palette = document.querySelector('.palette');
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
const BASE_COAT = '#EADFE3'; // прозрачная база — с неё начинается «покраска» при загрузке
let paintTimer;

// Меняет цвет лака: свечение и основа перетекают плавно, сверху проходит «кисть»
function paint(shade) {
  polishRoot.style.setProperty('--polish', shade.hex);
  if (reduceMotion) return;
  fan.style.setProperty('--next', shade.hex);
  fan.classList.remove('painting');
  void fan.offsetWidth; // перезапуск анимации кисти
  fan.classList.add('painting');
  clearTimeout(paintTimer);
  paintTimer = setTimeout(() => fan.classList.remove('painting'), 1100);
}

// Разбивает заголовок на слова, чтобы они поднимались по очереди
function splitWords(root) {
  let i = 0;
  const walk = node => {
    [...node.childNodes].forEach(child => {
      if (child.nodeType === Node.TEXT_NODE) {
        const frag = document.createDocumentFragment();
        child.textContent.split(/( +)/).forEach(part => {
          if (!part) return;
          if (/^ +$/.test(part)) { frag.append(part); return; }
          const outer = document.createElement('span');
          outer.className = 'w';
          const inner = document.createElement('span');
          inner.style.setProperty('--wi', i++);
          inner.textContent = part;
          outer.append(inner);
          frag.append(outer);
        });
        child.replaceWith(frag);
      } else if (child.nodeType === Node.ELEMENT_NODE) {
        walk(child);
      }
    });
  };
  walk(root);
  return i;
}

try {
  const words = splitWords(document.querySelector('.hero h1'));

  // Бегущая лента: 4 копии палитры, прокрутка на половину даёт бесшовный цикл
  const ticker = document.getElementById('ticker');
  for (let k = 0; k < 4; k++) {
    SHADES.forEach(s => {
      const item = document.createElement('span');
      item.className = 'ticker-item';
      // Собираем через DOM, а не innerHTML: текст никогда не превратится в разметку
      const dot = document.createElement('i');
      dot.style.setProperty('--c', s.hex);
      const code = document.createElement('small');
      code.textContent = `№ ${s.code}`;
      item.append(dot, `${s.name} `, code);
      ticker.append(item);
    });
  }

  // Лёгкий 3D-наклон палитры за курсором
  if (!reduceMotion && matchMedia('(hover: hover)').matches) {
    palette.addEventListener('pointermove', e => {
      const r = palette.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width - .5;
      const y = (e.clientY - r.top) / r.height - .5;
      palette.style.setProperty('--ty', (x * 8).toFixed(2) + 'deg');
      palette.style.setProperty('--tx', (-y * 8).toFixed(2) + 'deg');
    });
    palette.addEventListener('pointerleave', () => {
      palette.style.setProperty('--ty', '0deg');
      palette.style.setProperty('--tx', '0deg');
    });
  }

  // Веер сложен и покрыт прозрачной базой, пока его не видно.
  // Когда до него докрутили — раскрывается, и кисть кладёт «Сливу».
  if (!reduceMotion && 'IntersectionObserver' in window) {
    polishRoot.style.transition = 'none';
    polishRoot.style.setProperty('--polish', BASE_COAT);
    void polishRoot.offsetWidth;
    polishRoot.style.transition = '';
    fan.classList.add('pre');
    const fanObserver = new IntersectionObserver(entries => {
      if (!entries[0].isIntersecting) return;
      fan.classList.remove('pre');
      setTimeout(() => paint(state.shade), 700);
      fanObserver.disconnect();
      Logger.debug('fan.open', { fn: 'fanObserver' });
    }, { threshold: .45 });
    fanObserver.observe(fan);
  }
  Logger.debug('motion.init', { fn: 'initMotion', words, reduceMotion });
} catch (err) {
  Logger.error('motion.init.failed', err, { fn: 'initMotion' });
}

SHADES.forEach(s => {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'swatch';
  b.style.setProperty('--c', s.hex);
  b.setAttribute('aria-label', `№ ${s.code} ${s.name}`);
  b.setAttribute('aria-pressed', String(s === state.shade));
  b.addEventListener('click', () => {
    state.shade = s;
    paint(s);
    const nameEl = document.createElement('span');
    nameEl.textContent = s.name;
    label.replaceChildren(`№ ${s.code} `, nameEl);
    swatchBox.querySelectorAll('.swatch').forEach(x => x.setAttribute('aria-pressed', String(x === b)));
    syncNote();
    Logger.debug('palette.shade', { fn: 'onShadeClick', code: s.code });
  });
  swatchBox.appendChild(b);
});

document.querySelectorAll('.shape').forEach(b => {
  b.addEventListener('click', () => {
    state.shape = b.dataset.shape;
    fan.dataset.shape = state.shape;
    document.querySelectorAll('.shape').forEach(x => x.setAttribute('aria-pressed', String(x === b)));
    syncNote();
    Logger.debug('palette.shape', { fn: 'onShapeClick', shape: state.shape });
  });
});

noteField.addEventListener('input', () => { noteTouched = true; });
syncNote();

/* ================= Отзывы =================
   ПРИМЕРЫ — замените на настоящие отзывы.
   photo: путь к фото рядом с файлом, например 'photos/marina.jpg'.
   Пока photo пустое, карточка окрашена в оттенок лака клиентки. */
const REVIEWS = [
  { name: 'Марина', service: 'Маникюр + гель-лак', master: 'Алина', shade: SHADES[0], photo: 'data:image/webp;base64,',
    text: 'Хожу к Алине третий месяц. Покрытие держится ровно до следующей записи, ни одного скола. Инструмент при мне достают из крафт-пакета — для меня это важно.' },
  { name: 'Ольга', service: 'Педикюр + гель-лак', master: 'Катя', shade: SHADES[1], photo: 'data:image/webp;base64,',
    text: 'Катя очень бережно работает со стопами. Первый раз после педикюра не было ни одного пореза. Записалась сразу на следующий месяц.' },
  { name: 'Дарья', service: 'Наращивание, миндаль', master: 'Вера', shade: SHADES[2], photo: 'data:image/webp;base64,',
    text: 'Хотела длинный миндаль, но боялась, что будет мешать. Вера подобрала длину, с которой удобно печатать. Держится уже четвёртую неделю.' },
  // chip — своя подпись вместо оттенка из палитры (для дизайна из нескольких цветов)
  { name: 'Кира', service: 'Маникюр + яркий дизайн', master: 'Ника', shade: { code: '', name: '', hex: '#E0409A' }, chip: 'Неон-микс', photo: 'data:image/webp;base64,',
    text: 'Пришла с картинкой из интернета, а Ника предложила свой вариант — каждый ноготь своего цвета. Получилось даже лучше. Подруги спрашивают, где делала.' }
];
const CARD_TILT = [-7, 5, -3, 8];

(function initReviews() {
  const stack = document.getElementById('tStack');
  const body = document.getElementById('tBody');
  const count = document.getElementById('tCount');
  const box = document.getElementById('reviewsBox');
  let current = 0;
  let autoTimer;

  const cards = REVIEWS.map((r, i) => {
    const card = document.createElement('div');
    card.className = 't-card';
    card.style.setProperty('--c', r.shade.hex);
    if (r.photo) {
      card.classList.add('has-photo');
      card.style.setProperty('--photo', `url("${r.photo}")`);
    }
    const letter = document.createElement('span');
    letter.className = 't-letter';
    letter.textContent = r.name[0];
    const shade = document.createElement('span');
    shade.className = 't-chip shade';
    shade.textContent = r.chip || `№ ${r.shade.code} ${r.shade.name}`;
    const sample = document.createElement('span');
    sample.className = 't-chip sample';
    sample.textContent = 'пример';
    card.append(letter, shade, sample);
    stack.append(card);
    return card;
  });

  function layoutCards() {
    const n = cards.length;
    cards.forEach((card, i) => {
      const depth = (i - current + n) % n; // 0 — активная, дальше — глубже в стопке
      card.setAttribute('aria-hidden', String(depth !== 0));
      card.style.zIndex = String(n - depth);
      if (depth === 0) {
        card.style.transform = 'none';
        card.style.opacity = '1';
        card.style.filter = 'none';
      } else {
        card.style.transform = `rotate(${CARD_TILT[i % CARD_TILT.length]}deg) scale(${1 - depth * 0.04})`;
        card.style.opacity = '.85';
        card.style.filter = 'saturate(.7) brightness(.95)';
      }
    });
  }

  function renderText() {
    const r = REVIEWS[current];
    body.textContent = '';
    const name = document.createElement('h3');
    name.className = 't-name';
    name.textContent = r.name;
    const role = document.createElement('p');
    role.className = 't-role';
    role.textContent = `${r.service} · мастер ${r.master}`;
    const quote = document.createElement('p');
    quote.className = 't-quote';
    r.text.split(' ').forEach((word, i) => {
      const w = document.createElement('span');
      w.style.setProperty('--i', i);
      w.textContent = word;
      quote.append(w, ' ');
    });
    body.append(name, role, quote);
    count.textContent = `${current + 1} / ${REVIEWS.length}`;
  }

  function show(index, source) {
    current = (index + REVIEWS.length) % REVIEWS.length;
    layoutCards();
    renderText();
    const card = cards[current];
    card.classList.remove('jump');
    void card.offsetWidth; // перезапуск прыжка
    card.classList.add('jump');
    Logger.debug('reviews.show', { fn: 'showReview', index: current, source });
  }

  function startAuto() {
    if (reduceMotion) return;
    clearInterval(autoTimer);
    autoTimer = setInterval(() => show(current + 1, 'auto'), 7000);
  }
  function stopAuto() { clearInterval(autoTimer); }

  try {
    document.getElementById('tPrev').addEventListener('click', () => { show(current - 1, 'prev'); startAuto(); });
    document.getElementById('tNext').addEventListener('click', () => { show(current + 1, 'next'); startAuto(); });
    box.addEventListener('keydown', e => {
      if (e.key === 'ArrowLeft') show(current - 1, 'key');
      if (e.key === 'ArrowRight') show(current + 1, 'key');
    });
    // Автопрокрутка на паузе, пока человек читает или пользуется кнопками
    box.addEventListener('pointerenter', stopAuto);
    box.addEventListener('pointerleave', startAuto);
    box.addEventListener('focusin', stopAuto);
    box.addEventListener('focusout', startAuto);

    layoutCards();
    renderText();
    startAuto();
  } catch (err) {
    Logger.error('reviews.init.failed', err, { fn: 'initReviews', count: REVIEWS.length });
  }
})();

/* ================= Форма записи ================= */
const form = document.getElementById('bookForm');
const dateInput = document.getElementById('f-date');
const timeSelect = document.getElementById('f-time');
const result = document.getElementById('result');

function isoToday() {
  const d = new Date();
  return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
}
dateInput.min = isoToday();

for (let h = 9; h <= 19; h++) {
  ['00', '30'].forEach(m => {
    const o = document.createElement('option');
    o.textContent = `${h}:${m}`;
    timeSelect.appendChild(o);
  });
}
timeSelect.value = '12:00';

function showErr(id, show) { document.getElementById(id).hidden = !show; }

// Галочка «заявка сформирована» — SVG через DOM, без innerHTML
function checkIcon() {
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('class', 'check');
  svg.setAttribute('viewBox', '0 0 26 26');
  svg.setAttribute('aria-hidden', 'true');
  const circle = document.createElementNS(NS, 'circle');
  circle.setAttribute('cx', '13');
  circle.setAttribute('cy', '13');
  circle.setAttribute('r', '12');
  const path = document.createElementNS(NS, 'path');
  path.setAttribute('d', 'M7.5 13.5l3.8 3.8 7.2-7.6');
  svg.append(circle, path);
  return svg;
}

form.addEventListener('submit', e => {
  e.preventDefault();
  const requestId = 'bk_' + Date.now().toString(36);
  try {
    const data = Object.fromEntries(new FormData(form));
    const digits = (data.phone || '').replace(/\D/g, '');
    const errors = {
      name: !data.name.trim(),
      phone: digits.length !== 11,
      date: !data.date || data.date < isoToday()
    };
    showErr('e-name', errors.name);
    showErr('e-phone', errors.phone);
    showErr('e-date', errors.date);

    if (Object.values(errors).some(Boolean)) {
      Logger.warn('booking.invalid', { fn: 'onSubmit', requestId, fields: Object.keys(errors).filter(k => errors[k]) });
      return;
    }

    const niceDate = new Date(data.date + 'T00:00').toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', weekday: 'long' });
    result.replaceChildren();
    const title = document.createElement('div');
    title.className = 'result-head';
    const bold = document.createElement('b');
    bold.textContent = 'Заявка сформирована';
    title.append(checkIcon(), bold);
    const body = document.createElement('p');
    body.textContent = `${data.name.trim()}, ${data.service.toLowerCase()} — ${niceDate}, ${data.time}.`;
    const demo = document.createElement('p');
    demo.className = 'demo';
    demo.textContent = 'Демо-версия: отправка заявок в студию пока не подключена.';
    result.append(title, body, demo);
    result.hidden = false;

    // Телефон в лог не пишем целиком — только последние 2 цифры.
    Logger.info('booking.created', {
      fn: 'onSubmit', requestId, service: data.service, date: data.date, time: data.time,
      phoneMasked: '***' + digits.slice(-2), palette: paletteText()
    });
  } catch (err) {
    Logger.error('booking.failed', err, { fn: 'onSubmit', requestId });
  }
});

Logger.info('page.loaded', { fn: 'init', shades: SHADES.length });
